    /**
     * Tests getting all NetworkProfiles.
     *
     * @return    Collection
     */
    public List<NetworkProfile> testGetAll() throws Throwable {
    LOGGER.info( "NetworkProfileTest:testGetAll() - Retrieving Collection of NetworkProfiles:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all NetworkProfile : " );
    List<NetworkProfile> collection  = null;

    try {
        // call the static get method on the NetworkProfileService
        collection = service.getAllNetworkProfile();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            NetworkProfile currEntity  = null;
            Iterator<NetworkProfile> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getNetworkProfileId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

